import { Router } from "express";
import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";
import { config } from "../../config/env";
import { auth } from "../../middleware/auth";
import db from "../../db/database";

const router = Router();
router.post("/ask", auth, async (req, res) => {
  try {
    const { prompt, files } = req.body;
    let apiKey = process.env.GEMINI_API_KEY;
    if (apiKey === 'MY_GEMINI_API_KEY' || apiKey === 'dummy' || apiKey === 'your_api_key_here') {
      apiKey = undefined; 
    }
    const ai = new GoogleGenAI(apiKey ? { apiKey } : {});
    
    // Create the search tool
    const searchLegalDocumentsTool: FunctionDeclaration = {
      name: "search_legal_documents",
      description: "Tra cứu các văn bản pháp luật hiện hành trong kho dữ liệu của công ty bằng từ khóa liên quan.",
      parameters: {
        type: Type.OBJECT,
        properties: {
          query: {
            type: Type.STRING,
            description: "Từ khóa tìm kiếm (VD: 'Luật doanh nghiệp', 'ly hôn', 'hợp đồng thành lập')."
          }
        },
        required: ["query"]
      }
    };
    
    const parts: any[] = [];
    if (prompt && prompt.trim() !== "") {
      parts.push({ text: prompt });
    }
    if (files && files.length > 0) {
      for (const f of files) {
        parts.push({ inlineData: { mimeType: f.mimeType, data: f.data } });
      }
    }
    if (parts.length === 0) {
      parts.push({ text: "Xin chào, bạn có thể giúp gì cho tôi?" });
    }
    
    // System instructions to guide the AI
    const systemInstruction = 
      "Bạn là một trợ lý pháp lý AI xuất sắc của công ty Luật TNHH Ánh Dương. " +
      "Nhiệm vụ của bạn là hỗ trợ luật sư và nhân viên công ty tra cứu thông tin, phân tích hồ sơ và đưa ra các đề xuất về pháp lý. " +
      "Hãy sử dụng công cụ 'search_legal_documents' nếu câu hỏi liên quan đến hoặc cần tham chiếu các văn bản pháp luật, luật hoặc nội quy đang áp dụng. Sau đó trích dẫn thông tin để phân tích hồ sơ vụ án cho chính xác nhất.";

    // Start a chat session or generate content with tools
    let chat;
    let modelResponse;
    
    try {
      chat = await ai.chats.create({
        model: "gemini-3.5-flash",
        config: {
          systemInstruction: systemInstruction,
          tools: [{ functionDeclarations: [searchLegalDocumentsTool] }]
        }
      });
      modelResponse = await chat.sendMessage({ parts } as any);
    } catch(err) {
      // Fallback
      console.log(err);
      const result = await ai.models.generateContent({
        model: "gemini-3.5-flash",
        contents: [{ role: "user", parts: parts }],
        config: { systemInstruction: systemInstruction }
      });
      return res.json({ text: result.text });
    }

    let finalResponseText = modelResponse.text || "";
    
    // Handle function calls
    if (modelResponse.functionCalls && modelResponse.functionCalls.length > 0) {
      for (const call of modelResponse.functionCalls) {
        if (call.name === "search_legal_documents") {
          const query = (call.args as any)?.query || "";
          
          let results: any[] = [];
          try {
             const docs = db.prepare(`SELECT title, document_number, issue_date, content FROM legal_documents WHERE title LIKE ? OR content LIKE ? COLLATE NOCASE LIMIT 20`).all(`%${query}%`, `%${query}%`);
             results = docs;
          } catch(e) {}
          
          const functionResponseParts = [{
             functionResponse: {
                name: "search_legal_documents",
                response: { results: results }
             }
          }];

          const secondResponse = await chat.sendMessage(functionResponseParts as any);
          finalResponseText = secondResponse.text || "";
        }
      }
    }
    
    res.json({ text: finalResponseText });
  } catch (error: any) {
    console.error("AI Route Error:", error);
    const errorStr = error.message || String(error);
    if (errorStr.includes('API key not valid') || errorStr.includes('API_KEY_INVALID') || errorStr.includes('API key not valid')) {
      return res.status(400).json({ error: "API Key không hợp lệ. Vui lòng cập nhật API Key chính xác trên hệ thống." });
    }
    res.status(500).json({ error: error.message || "Lỗi khi xử lý với AI." });
  }
});

export default router;
