import { Router } from "express";
import { auth } from "../../middleware/auth";
import db from "../../db/database";
import jwt from "jsonwebtoken";
import { config } from "../../config/env";
import bcrypt from "bcrypt";
import { validatePassword } from "../../utils/password";

const router = Router();

router.post("/login", (req: any, res: any) => {
  console.log("Login request secure:", req.secure, "protocol:", req.protocol, "headers:", req.headers['x-forwarded-proto']);
  const { username, password } = req.body;
  const dbUser: any = db.prepare(`SELECT * FROM users WHERE username = ?`).get(username);

  let isValid = false;

  if (dbUser) {
    if (dbUser.password && (dbUser.password.startsWith('$2b$') || dbUser.password.startsWith('$2a$'))) {
      isValid = bcrypt.compareSync(password, dbUser.password);
    } else {
      // Plain text fallback (for soft migration)
      isValid = (dbUser.password === password);
      // Migrate password to hash if it was valid
      if (isValid) {
        const hashed = bcrypt.hashSync(password, 10);
        db.prepare('UPDATE users SET password = ? WHERE id = ?').run(hashed, dbUser.id);
      }
    }
  }

  if (isValid) {
    const user = db.prepare(`SELECT id, username, name, role, title, staff_code, branch, start_date, contract_type, contract_sign_date, salary, bonus, avatar, phone, email, dob, gender, address FROM users WHERE id = ?`).get((dbUser as any).id);
    req.session.user = user;
    const token = jwt.sign(user as object, config.SESSION_SECRET || 'secret', { expiresIn: '24h' });
    res.json({ success: true, user, token });
  } else {
    res.status(401).json({ success: false, message: "Tên đăng nhập hoặc mật khẩu không đúng" });
  }
});

router.post("/logout", auth, (req: any, res: any) => {
  if (req.session) {
    req.session.destroy();
  }
  res.json({ success: true });
});

router.get("/me", auth, (req: any, res: any) => {
  if (req.session?.user?.id) {
    const user = db.prepare(`SELECT id, username, name, role, title, staff_code, branch, start_date, contract_type, contract_sign_date, salary, bonus, avatar, phone, email, dob, gender, address FROM users WHERE id = ?`).get(req.session.user.id);
    if (user) {
      req.session.user = user;
      return res.json({ user });
    }
  }
  res.json({ user: req.session.user });
});

router.post("/change-password", auth, (req: any, res: any) => {
  const { currentPassword, newPassword } = req.body;
  const userId = req.session?.user?.id;

  if (!userId || !currentPassword || !newPassword) {
    return res.status(400).json({ success: false, message: "Thiếu thông tin" });
  }

  const passwordError = validatePassword(newPassword);
  if (passwordError) {
    return res.status(400).json({ success: false, message: passwordError });
  }

  const dbUser: any = db.prepare(`SELECT * FROM users WHERE id = ?`).get(userId);
  if (!dbUser) {
    return res.status(404).json({ success: false, message: "Không tìm thấy người dùng" });
  }

  let isValid = false;
  if (dbUser.password && (dbUser.password.startsWith('$2b$') || dbUser.password.startsWith('$2a$'))) {
    isValid = bcrypt.compareSync(currentPassword, dbUser.password);
  } else {
    isValid = (dbUser.password === currentPassword);
  }

  if (!isValid) {
    return res.status(401).json({ success: false, message: "Mật khẩu hiện tại không đúng" });
  }

  const hashedNewPassword = bcrypt.hashSync(newPassword, 10);
  db.prepare('UPDATE users SET password = ? WHERE id = ?').run(hashedNewPassword, userId);

  res.json({ success: true, message: "Đổi mật khẩu thành công" });
});

export default router;
