import { Router } from "express";
import { auth, requirePermission } from "../../middleware/auth";
import db from "../../db/database";
import { v4 as uuidv4 } from "uuid";
import { logAction } from "../../utils/logger";
import bcrypt from "bcrypt";
import { validatePassword } from "../../utils/password";

const router = Router();
const canManageUsers = requirePermission("manageUsers");

/* EMPLOYEE */
router.post("/employee", canManageUsers, (req: any, res: any) => {
  const { name, position, salary, dependents } = req.body;
  db.prepare(`INSERT INTO employees VALUES (?,?,?,?,?)`).run(
    uuidv4(), name, position, salary, dependents
  );
  logAction(req.session.user, "ADD_EMPLOYEE");
  res.json({ success: true });
});

router.get("/employees", auth, (req: any, res: any) => {
  const employees = db.prepare(`SELECT * FROM employees`).all();
  res.json(employees);
});

/* USERS */
router.get("/users", auth, (req: any, res: any) => {
  const users = db.prepare(`SELECT id, username, name, role, title, staff_code, branch, start_date, contract_type, contract_sign_date, salary, bonus, avatar, phone, email, dob, gender, address FROM users`).all();
  res.json(users);
});

router.post("/users", canManageUsers, (req: any, res: any) => {
  try {
    const data = req.body;
    
    if (data.password) {
      const passwordError = validatePassword(data.password);
      if (passwordError) {
        return res.status(400).json({ error: passwordError });
      }
    }

    const fields = ['username', 'password', 'name', 'role', 'title', 'staff_code', 'branch', 'start_date', 'contract_type', 'contract_sign_date', 'salary', 'bonus', 'avatar', 'phone', 'email', 'dob', 'gender', 'address'];
    let keys: string[] = [];
    let values: string[] = [];
    let params: any[] = [];
    
    for (const field of fields) {
      if (data[field] !== undefined) {
        keys.push(field);
        values.push('?');
        let val = data[field];
        if (field === 'password' && val) {
          val = bcrypt.hashSync(val.toString(), 10);
        }
        params.push(val);
      }
    }
    
    if (keys.length > 0) {
      const query = `INSERT INTO users (${keys.join(', ')}) VALUES (${values.join(', ')})`;
      db.prepare(query).run(...params);
    }
    res.json({ success: true });
  } catch (error: any) {
    console.error('Error inserting user:', error);
    res.status(500).json({ success: false, message: error.message });
  }
});

router.put("/users/:id", auth, (req: any, res: any) => {
  try {
    const userId = req.params.id;
    const currentUser = req.session?.user;

    if (!currentUser) return res.status(401).json({ error: "login required" });

    // Check permissions
    const currentUserPerms = db.prepare(`SELECT manageUsers FROM role_permissions WHERE role=?`).get(currentUser.role || "") as any;
    const canManage = currentUserPerms?.manageUsers || currentUser.role === 'admin' || currentUser.role === 'Admin';
    if (!canManage && currentUser.id.toString() !== userId) {
       return res.status(403).json({ error: "permission denied" });
    }

    const data = req.body;
    
    // Non-admins can't change their role or sensitive fields
    if (!canManage) {
      delete data.role;
      delete data.salary;
      delete data.bonus;
      delete data.title;
      delete data.staff_code;
      delete data.branch;
      delete data.start_date;
      delete data.contract_type;
      delete data.contract_sign_date;
    }

    if (data.password) {
      const passwordError = validatePassword(data.password);
      if (passwordError) {
        return res.status(400).json({ error: passwordError });
      }
    }

    const fields = ['username', 'password', 'name', 'role', 'title', 'staff_code', 'branch', 'start_date', 'contract_type', 'contract_sign_date', 'salary', 'bonus', 'avatar', 'phone', 'email', 'dob', 'gender', 'address'];
    let updates: string[] = [];
    let params: any[] = [];
    
    for (const field of fields) {
      if (data[field] !== undefined) {
        // If updating password to empty, we skip or hash the new one
        if (field === 'password') {
          if (!data[field]) continue; // If empty string passed, don't update password
          updates.push(`${field}=?`);
          params.push(bcrypt.hashSync(data[field].toString(), 10));
        } else {
          updates.push(`${field}=?`);
          params.push(data[field]);
        }
      }
    }
    
    if (updates.length > 0) {
      const query = `UPDATE users SET ${updates.join(", ")} WHERE id=?`;
      params.push(userId);
      db.prepare(query).run(...params);
    }
    
    res.json({ success: true });
  } catch (error: any) {
    console.error('Error updating user:', error);
    res.status(500).json({ success: false, message: error.message });
  }
});

router.delete("/users/:id", canManageUsers, (req: any, res: any) => {
  db.prepare(`DELETE FROM users WHERE id=?`).run(req.params.id);
  res.json({ success: true });
});

export default router;
